#!/usr/bin/env bash
# manual-install.sh — self-contained (no repo clone required).
# Generated by tools/gen-manual.sh from the mac-setup dotfiles.
#
#   INSTALL_PORTS=0 bash manual-install.sh   # only write config files
#   bash manual-install.sh                   # write configs + install ports
set -euo pipefail

INSTALL_PORTS="${INSTALL_PORTS:-1}"
say() { printf '==> %s\n' "$*"; }

write_file() {
  local dest="$1"
  mkdir -p "$(dirname "$dest")"
  if [ -e "$dest" ] && [ ! -L "$dest" ]; then
    cp "$dest" "$dest.bak.$(date +%s)"
  fi
  cat > "$dest"
}

if [ "$INSTALL_PORTS" = "1" ]; then
  if ! xcode-select -p >/dev/null 2>&1; then
    say "Installing Xcode Command Line Tools (finish the dialog, then re-run)..."
    xcode-select --install || true
  fi
  if [ ! -x /opt/local/bin/port ]; then
    echo "MacPorts is not installed. Install the macOS 26 .pkg from"
    echo "https://www.macports.org/install.php and re-run this script."
    exit 1
  fi
  export PATH="/opt/local/bin:/opt/local/sbin:$PATH"
  say "Updating MacPorts (sudo port selfupdate)..."
  sudo port selfupdate
  say "Installing ports..."
  sudo port install neovim ripgrep fd fzf lazygit tree-sitter-cli \
    nodejs22 python312 go tmux starship git kitty
  sudo port select --set python3 python312 || true
  sudo port select --set nodejs  nodejs22  || true
  if command -v infocmp >/dev/null 2>&1 && ! infocmp tmux-256color >/dev/null 2>&1; then
    say "Adding tmux-256color terminfo (fallback)..."
    curl -fsSL https://raw.githubusercontent.com/tmux/tmux/master/terminfo/t/tmux-256color \
      | tic -x -o "$HOME/.terminfo" - || true
  fi
  say "Installing Maple Mono NF font..."
  FONT_URL="$(curl -fsSL https://api.github.com/repos/subframe7536/maple-font/releases/latest 2>/dev/null | grep -oE 'https://[^"]*MapleMono-NF\.zip' | head -1 || true)"
  if [ -n "${FONT_URL:-}" ]; then
    tmp="$(mktemp -d)"
    curl -fsSL "$FONT_URL" -o "$tmp/MapleMono-NF.zip"
    mkdir -p "$HOME/Library/Fonts"
    unzip -oq "$tmp/MapleMono-NF.zip" -d "$HOME/Library/Fonts/"
    xattr -cr "$HOME"/Library/Fonts/MapleMono-NF*.ttf 2>/dev/null || true
    rm -rf "$tmp"
  else
    say "WARN: install Maple Mono NF manually from"
    say "https://github.com/subframe7536/maple-font/releases into ~/Library/Fonts"
  fi
fi

say "Writing config files..."

